        found.push_back(json{{"catalogId", printer->id},
                             {"brand", printer->vendor_name},
                             {"model", printer->model_name},
                             {"buildVolume", printer->build_volume},
                             {"nozzles", printer->nozzles},
                             {"assumed", json{{"nozzle", nozzle},
